INSERT INTO `terms` VALUES (1,0,'Page','empty.png','p',0,0,'Page',0),(2,1,'Questions','empty.png','questions',0,0,'Questions',0),(3,1,'Topick','empty.png','topick',0,0,'Topick',0),(4,0,'मानव का इतिहास','human-history.png','human-history',1,1,'मानव का इतिहास लाखों वर्षों में विकसित होने वाली घटनाओं और विकास का क्रम है। इसे मुख्य रूप से चार प्रमुख चरणों में विभाजित किया जा सकता है- प्रागैतिहासिक युग (Prehistoric Era), प्राचीन युग (Ancient Era), मध्यकाल (Medieval Era), आधुनिक युग (Modern Era) इन चरणों के माध्यम से मानव ने सभ्यता, संस्कृति, और विज्ञान में प्रगति की, जिससे आधुनिक समाज का निर्माण हुआ।',0),(5,0,'इस्लामिक समाज','islamic-society.png','islamic-society',1,1,'इस्लामिक समाज एक धार्मिक समुदाय है जो इस्लाम धर्म के मान्यताओं और शिक्षाओं पर आधारित है। इस्लामिक समाज में एक मुस्लिम व्यक्ति की पहचान और उनके समूह के सदस्यता मुख्य धार्मिक श्रेणियों में आती है। इस्लामिक समाज में मस्जिद और ईदगाह जैसे स्थानों पर धार्मिक कार्यक्रमों का आयोजन किया जाता है। इस्लामिक समाज में विवाह, उपवास, धर्मोत्सव, और अन्य धार्मिक आयोजनों के लिए नियमों और परंपराओं का पालन किया जाता है। इस्लामिक समाज की अधिकांश विश्वासों और अदान-प्रदानों में इमाम, मौलवी, और उलेमा के नेतृत्व में आधारित होती है।',8),(6,0,'चीन का इतिहास','china-map.png','history-of-china',1,1,'चीन का इतिहास विशालकार और समृद्ध है। इसमें प्राचीन की शिक्षाओं, बौद्ध धर्म के उदय, दाऊदायों और मिंग साम्राज्यों की उत्थान, और माओ ज़ेडोंग की आधुनिकीकरण तक की कई घटनाएं शामिल हैं। चीनी सभ्यता ने विज्ञान, प्रौद्योगिकी, और फिलॉसफी में महत्वपूर्ण योगदान दिया है। यह एक बड़े और प्रभावशाली राष्ट्र है जिसका इतिहास उसकी विविधता और प्राचीनता को दर्शाता है।',2),(7,0,'चीन में साम्यवाद','communism-in-china.png','communism-in-china',1,1,'चीन में साम्यवाद (सोशलिज्म) एक विचारधारा और राजनीतिक प्रणाली है जो कम्युनिस्ट पार्टी ऑफ़ चीन (सीसीपी) के नेतृत्व में आत्मसमर्पित है। यह विचारधारा चीनी लोगों के समृद्धि और समाज को अधिकतम कल्याण की दिशा में ले जाने का उद्देश्य रखती है।',5),(8,0,'जापान का इतिहास','history-of-japan.png','history-of-japan',1,1,'जापान का इतिहास बहुत प्राचीन है और विविधता से भरा हुआ है। प्राचीन काल में, जापान में शिंतो धर्म का प्राचीन सम्राटों द्वारा प्रचार किया गया। 7वीं और 8वीं सदियों में, नारा और हेईयन काल में, जापान में बौद्ध धर्म का प्रचार हुआ। 12वीं और 19वीं सदियों में, कमाकुरा, अशिकागा, और तोकुगावा शासकों के राजाओं ने जापान की राजनीतिक संरचना को परिवर्तित किया। 19वीं और 20वीं सदी में, जापान ने अपने अभिन्नता की प्रतिष्ठा बढ़ाने के लिए उदारीकृत किया और इम्पीरियलिज्म की दिशा में अग्रसर हुआ। द्वितीय विश्वयुद्ध के बाद, जापान ने आर्थिक उत्थान और औद्योगिकीकरण के माध्यम से विश्व अर्थव्यवस्था में अहम भूमिका निभाई। आज, जापान एक उच्च आर्थिक विकास और विश्वासी राजनीतिक शक्ति है।',2),(9,0,'झारखण्ड ','jharkhand.webp','jharkhand',1,1,'झारखण्ड भारत का एक राज्य है, जो 2000 में बिहार से अलग किया गया। इसका राजधानी रांची है। झारखण्ड का नाम संगठनवादी आंदोलन के प्रेरक, भूमिहार लोहा उपखंड के \'झार\' और खनन के लिए \'खण्ड\' से लिया गया है। झारखण्ड का क्षेत्रफल लगभग 79,710 वर्ग किलोमीटर है। यहां चोटनागपुर प्लेटो और सान्देह जंगल प्रदेश सहित अनेक प्राकृतिक संपदाएं हैं। झारखण्ड की अर्थव्यवस्था का मुख्य आधार खनिज और उद्योग है, जैसे कि अग्निशामक, खनिज तेल, ऊर्जा संसाधन और इंफ्रास्ट्रक्चर उद्योग।',10),(10,0,'द्वितीय विश्वयुद्ध','war.png','second-world-war',1,1,'द्वितीय विश्वयुद्ध (Second World War) दुनिया के दोनों ओर से एक विशालकार युद्ध था जो 1939 से 1945 तक चला। इस युद्ध में अधिकांश विश्व के राष्ट्रों ने शामिल होकर एक संघर्ष में भाग लिया, जिसमें नाजी जर्मनी, इटली, और जापान जैसे राष्ट्र विशेष रूप से विशेषज्ञ थे। इस युद्ध के मुख्य कारणों में राजनीतिक और आर्थिक विवाद, जवाहरी लाल नेहरू के नेतृत्व में कांग्रेस द्वारा भारत की स्वतंत्रता के लिए आयोजित व्यक्तिगत और सार्वजनिक अद्यतन शामिल हैं। इसके दौरान भारत ने ब्रिटिश शासन के खिलाफ सक्रिय भूमिका निभाई, जिसने स्वतंत्रता की दिशा में एक महत्वपूर्ण परिवर्तन किया।',0),(11,0,'धर्म सुधार आंदोलन','religious-reform-movement.png','religious-reform-movement',1,1,'धर्म सुधार आंदोलन भारतीय समाज के धार्मिक और सामाजिक सुधार के लिए आयोजित किया गया था। इस आंदोलन का मुख्य उद्देश्य जाति और अंतर-जाति समाज के असमानता और अत्याचार के खिलाफ लड़ाई लड़ना था। यह आंदोलन भारत में विभिन्न धार्मिक समुदायों के नेताओं द्वारा आयोजित किया गया, जैसे कि राजा राममोहन राय, स्वामी दयानंद सरस्वती, और बाबा साहेब भीमराव आंबेडकर जैसे महापुरुष। इस आंदोलन के माध्यम से, समाज ने जातिवाद, अंतर-जाति विवाह, और अन्य असमानताओं के खिलाफ सामूहिक रूप से विरोध दिया। धर्म सुधार आंदोलन ने भारतीय समाज को एक मानवीय और समान समाज की दिशा में प्रगति किया।',2),(12,0,'पलामू','palamu.png','palamu',1,1,'पलामू भारतीय राज्य झारखंड का उत्तर-पश्चिमी जिला है।जो 1 जनवरी 1892, में ब्रिटिश राज के दौरान स्तापित हुआ था। जिले का मुख्यालय मेदिनीनगर है जो उत्तर कोयल नदी के दाहिने तट पर स्थित है और 1962 का बसा हुआ है। पलामू जिला झारखंड का सबसे पश्चिमी जिला है और इसकी सीमा पर बिहार राज्य के साथ मिलती है। यह चोटीयों, नदियों और वन्यजन से भरा हुआ है।',0),(13,0,'पूँजीवाद','capitalism.png','capitalism',1,1,'पूँजीवादी एक आर्थिक सिद्धांत है जो धन और संपत्ति की प्राथमिकता पर आधारित है। इस सिद्धांत में धन की अधिकता और वित्तीय संपत्ति का प्रबंधन महत्वपूर्ण माना जाता है। पूँजीवादी विचारधारा में लोग आर्थिक स्वतंत्रता, व्यापार, और निजी संपत्ति के महत्व को मानते हैं। इसका मुख्य उद्देश्य लाभ की प्राप्ति और धन के निर्माण में संलग्नता है। पूँजीवादी आर्थिक प्रणाली को अनेक देशों और समाजों में अपनाया गया है, और यह व्यापार, निवेश, बाजार, और उत्पादन की वृद्धि के लिए महत्वपूर्ण माना जाता है।',1),(14,0,'प्रथम विश्वयुद्ध','war.png','first-world-war',1,1,'प्रथम विश्वयुद्ध (1914-1918) एक विशालकार ग्लोबल संघर्ष था, जिसमें विभिन्न देशों और संघर्षशील ग्रुपों ने भाग लिया। यह युद्ध मुख्य रूप से यूरोप, एशिया, और अफ्रीका को शामिल करता था। इसकी मुख्य कारणों में राजनीतिक गहराई, आर्थिक विवाद, आर्थिक संघर्ष, जनसंख्या के वृद्धि, और आर्थिक प्रतिबंध थे। यह युद्ध विश्व इतिहास का एक महत्वपूर्ण अध्याय है, जिसका परिणाम न केवल मिलिटरी और राजनीतिक बदलावों में था, बल्कि इसने समाज और विचार में भी गहरी प्रभाव डाला। यह युद्ध बहुत से देशों के सीमाओं, राजनीतिक ढांचे, और समाजों के ढांचे को परिभाषित किया और वैश्विक इतिहास को अनगिनत उतार-चढ़ावों में डाल दिया।',4),(15,0,'बिहार ','bihar-map.png','bihar',1,1,'बिहार भारत के पूर्वी हिस्से में स्थित एक महत्वपूर्ण राज्य है, जिसका ऐतिहासिक, सांस्कृतिक और राजनीतिक महत्व बहुत अधिक है। बिहार का नामकरण \"विहार\" शब्द से हुआ है, जिसका अर्थ है बौद्ध मठ। यह राज्य भारत की सभ्यता और संस्कृति के विकास में एक प्रमुख भूमिका निभाता आया है।',0),(16,0,'बोल्शेविक क्रांति','bolshevik-revolution.png','bolshevik-revolution',1,1,'बोल्शेविक क्रांति, जिसे रूसी साम्राज्य की संघर्षी शासकांग और कम्युनिस्ट पार्टी के नेतृत्व में आयोजित किया गया, रूस में राजनीतिक परिवर्तन का महत्वपूर्ण चरण था। यह क्रांति 1917 में लेनिन के नेतृत्व में हुई थी और रूसी साम्राज्य को अधिकार में लाया और बाद में सोवियत संघ की नींव रखी। इस क्रांति के बाद, कम्युनिस्ट पार्टी ने रूस में एक साम्राज्य के रूप में सत्ता स्थापित की और सोवियत सोशलिस्ट गणराज्य की शुरुआत की। यह क्रांति दुनिया की इतिहास में एक महत्वपूर्ण स्थान रखती है, क्योंकि यह एक साम्राज्य को गिराने और एक नई और अद्वितीय राजनीतिक प्रणाली की शुरुआत करने के रूप में व्यक्ति राष्ट्र की भूमिका निभाई।',1),(17,0,'भारत की राज्यव्यवस्था','polity-of-bharat.png','polity-of-bharat',1,1,'भारत की राज्यव्यवस्था एक संघीय संसदीय लोकतंत्र है, जिसमें केंद्र और राज्यों के बीच शक्तियों का विभाजन होता है। इसका आधार भारतीय संविधान है, जो देश की सबसे महत्वपूर्ण कानूनी दस्तावेज है।',3),(18,0,'भारत छोड़ो आन्दोलन','quit-india-movement.png','quit-india-movement',1,1,'भारत छोड़ो आंदोलन, जिसे \"Quit India Movement\" भी कहा जाता है, भारतीय स्वतंत्रता संग्राम का एक महत्वपूर्ण चरण था। यह आंदोलन 1942 में भारतीय राष्ट्रीय कांग्रेस द्वारा आयोजित किया गया था। इस आंदोलन का मुख्य नारा था \"भारत छोड़ो\" यानी ब्रिटिशों को भारत छोड़ने का आदेश देने का दबाव डालना। इस आंदोलन में भारतीय जनता ने विभिन्न राजनीतिक, सामाजिक, और आर्थिक प्रयासों के माध्यम से ब्रिटिश सरकार के खिलाफ संघर्ष किया। भारतीय स्वतंत्रता संग्राम के इस अद्वितीय चरण ने भारतीय जनता की अजानबी और समर्थन को दर्शाया, जिसका परिणाम स्वतंत्रता की जीत में था।',8),(19,0,'भारतीय का इतिहास','history-of-india.png','history-of-india',1,1,'भारतीय इतिहास विशालकार और समृद्ध है। इसमें प्राचीन सभ्यताओं का उदय, महाजनपद, मौर्य, गुप्त, और मुघल साम्राज्यों का उदय और अवश्यकता के साथ ब्रिटिश साम्राज्य की आवश्यकता, स्वतंत्रता संग्राम, और 1947 में भारत की स्वतंत्रता शामिल है। इसके बाद के काल में, आधुनिक भारत का विकास, आर्थिक और सामाजिक प्रगति, और राजनीतिक प्रणाली का विकास भी शामिल है।',64),(20,0,'भारतीय स्वतंत्रता आंदोलन','empty.png','indian-independence-movement',1,1,'भारतीय स्वतंत्रता आंदोलन भारत के ब्रिटिश शासन से मुक्ति प्राप्त करने के लिए किए गए संघर्षों का एक अहम अध्याय था। इसमें अनेक विभिन्न आंदोलनों, सत्याग्रहों, और विद्रोहों के माध्यम से भारतीय जनता ने आजादी के लिए समर्थन दिया। इस आंदोलन के प्रमुख नेता महात्मा गांधी, भगत सिंह, सुभाष चंद्र बोस, जवाहरलाल नेहरू, और सरदार वल्लभभाई पटेल आदि थे। भारतीय स्वतंत्रता आंदोलन ने 1947 में भारत को स्वतंत्रता दिलाई।',12),(21,0,'मध्य प्रदेश','empty.png','madhya-pradesh',1,1,'मध्य प्रदेश भारत का एक महत्वपूर्ण राज्य है, जो अपनी भौगोलिक स्थिति, समृद्ध सांस्कृतिक धरोहर, ऐतिहासिक महत्व और प्राकृतिक सौंदर्य के लिए जाना जाता है। \"भारत का हृदय\" कहे जाने वाले इस राज्य का केंद्रीय स्थान इसे रणनीतिक और आर्थिक दृष्टि से महत्वपूर्ण बनाता है।',1),(22,0,'महामंदी','great-depression.png','great-depression',1,1,'महामंदी एक बड़ी आर्थिक मंदी को दर्शाता है जो एक या अधिक विशेष क्षेत्रों या व्यापारिक क्षेत्रों में व्याप्त होती है। इसके परिणामस्वरूप, उत्पादन, रोजगार, और आय में कमी होती है, जिससे आर्थिक संगठन में व्यवस्थित संकट उत्पन्न होता है।',2),(23,0,'राजव्यवस्था','empty.png','arrangement-of-the-governance',1,1,'राजव्यवस्था एक ऐसा ढाँचा है जिसके माध्यम से किसी देश, राज्य या समाज की शासन व्यवस्था संचालित होती है। यह विभिन्न संस्थाओं, नीतियों, कानूनों और प्रक्रियाओं का समूह होता है जो समाज में व्यवस्था, न्याय और सुरक्षा सुनिश्चित करने के लिए कार्य करता है। राजव्यवस्था का मुख्य उद्देश्य समाज के सभी वर्गों के बीच संतुलन बनाए रखना और समृद्धि, विकास तथा शांति को बढ़ावा देना होता है।',2),(24,0,'राजस्थान','empty.png','rajasthan',1,1,'राजस्थान भारत का सबसे बड़ा राज्य है, जो अपने समृद्ध इतिहास, जीवंत संस्कृति और राजसी स्थापत्य के लिए प्रसिद्ध है। यह राज्य पश्चिमी भारत में स्थित है और अपनी अनूठी भौगोलिक विविधता, जिसमें थार मरुस्थल भी शामिल है, के लिए जाना जाता है। राजस्थान की ऐतिहासिक और सांस्कृतिक संपन्नता इसे भारत के सबसे प्रमुख पर्यटन स्थलों में से एक बनाती है।',1),(25,0,'रूस का इतिहास','empty.png','historyof-russia',1,1,'रूस का इतिहास विस्तृत और विविध है। प्राचीन काल में, रूस क्षेत्र में विभिन्न स्लावी जनजातियों की स्थापना हुई। वे अपनी संस्कृति, भाषा, और धर्म के माध्यम से सामाजिक संरचना और राजनीतिक प्रणाली विकसित किए। मध्यकालीन युग में, रूसी अद्वीपराज्य ने विस्तार किया और एक शक्तिशाली राज्य की नींव रखी। 17वीं और 18वीं सदियों में, रूस के अंतिम तारा साम्राज्य की स्थापना हुई, जिसने विशाल साम्राज्य की शक्ति को प्रभावित किया। 20वीं सदी में, रूसी क्रांति और सोवियत संघ की स्थापना हुई, जो दुनिया के सबसे बड़े साम्यवादी राष्ट्रों में से एक बन गया। यहां पर केवल संक्षिप्त रूप में रूस के इतिहास का उल्लेख किया गया है, जिसमें विस्तारपूर्ण और महत्वपूर्ण घटनाओं की अनगिनत श्रृंखला है।',2),(26,0,'विश्व इतिहास','empty.png','world-history',1,1,'विश्व इतिहास का अध्ययन मानव सभ्यता के विकास, ऐतिहासिक घटनाओं, संस्कृति, और राजनीतिक प्रणालियों के प्रभाव को समझने के लिए किया जाता है। यह महत्वपूर्ण व्यक्तियों, समाजों, और घटनाओं के विश्वव्यापी परिणामों का अध्ययन करता है जो मानव इतिहास के पूर्वकाल से लेकर आधुनिक काल तक होते आए हैं।',17),(27,0,'वैदिक साहित्य','empty.png','vedic-literature',1,1,'वैदिक साहित्य भारतीय सभ्यता के प्राचीनतम साहित्यिक रचनाओं का संग्रह है, जो वेदों के रूप में प्रस्तुत किया गया है। इसमें चार मुख्य वेद हैं: ऋग्वेद, यजुर्वेद, सामवेद, और अथर्ववेद। ये वेद संस्कृत में लिखे गए हैं और वैदिक संस्कृति, धर्म, और ज्ञान को प्रकट करते हैं। वैदिक साहित्य में मंत्र, ऋचा, ब्राह्मण, आरण्यक, और उपनिषद् जैसे भेद होते हैं। इस साहित्य के माध्यम से हम भारतीय संस्कृति, धार्मिक तत्त्वों, और जीवन-दर्शन को समझते हैं।',6),(28,0,'व्यापार','empty.png','business',1,1,'व्यापार एक आर्थिक गतिविधि है जिसमें वस्त्र, उपकरण, सेवाएं, या अन्य वस्तुएं खरीदी और विक्रय की जाती हैं, आमतौर पर लाभ के लिए। यह व्यापारी और उपभोक्ता के बीच विनिमय के रूप में होता है और अलग-अलग बाजारों में स्थापित किए गए हो सकते हैं। व्यापार एक समाज में आर्थिक विकास का महत्वपूर्ण कारक होता है और विभिन्न विधियों में किया जा सकता है, जैसे कि व्यक्तिगत व्यापार, ऑनलाइन व्यापार, और अंतरराष्ट्रीय व्यापार। व्यापार आर्थिक संवृद्धि, रोजगार, और विकास में महत्वपूर्ण योगदान करता है।',1),(29,0,'साम्राज्यवाद','empty.png','imperialism',1,1,'साम्राज्यवाद एक राजनीतिक और सामाजिक प्रणाली है जिसमें एक शक्तिशाली एकल अधिकारिता या साम्राज्य राज्य का संचालन करता है। इस प्रणाली में साम्राज्य के संचालनकर्ता या साम्राज्यवादी स्वामी, राजा, या साम्राज्यवादी संगठन की प्रधानता होती है। इसमें साम्राज्यवादी साम्राज्य के अधीनस्थ राज्यों या क्षेत्रों को शासित करते हैं और साम्राज्य के लाभांश का उपयोग करते हैं। इस प्रणाली का इतिहास विभिन्न क्षेत्रों में उदाहरणों के रूप में मिलता है, जैसे कि रोमन साम्राज्य, मुघल साम्राज्य, और ब्रिटिश साम्राज्य।',2),(30,0,'सुमेरियन का इतिहास','empty.png','history-of-sumerian',1,1,'सुमेरियन सभ्यता को प्राचीन मेसोपोटामिया के क्षेत्र में स्थित उदाय किया जाता है। यह सभ्यता लगभग 3500 ईसा पूर्व से 2300 ईसा पूर्व तक रही। सुमेरियन सम्राट शुल्गी ने सबसे पहले सुमेर क्षेत्र को एकत्रित किया और सुमेर की पहली शहरी सभ्यता की स्थापना की। उन्होंने अनेक नगरों की नींव रखी और सुमेरियाई लोगों को संगठित किया। इस समय सुमेरियाई लोग खुदाई के द्वारा मिट्टी के बने उत्पादों के बदले में तामबे, पांच और सोने के उत्पादों को खरीदते थे और इसे बदलते थे। सुमेरियन सभ्यता में समुद्र के लिए जल यातायात बड़ी महत्ता रखता था और यह लोग समुद्र के माध्यम से विदेशों के साथ व्यापार करते थे।',1),(31,0,'सैन्यवाद','empty.png','militarism',1,1,'सैन्यवाद एक राजनीतिक और सामाजिक सिद्धांत है जो युद्ध और सेनाओं की महत्वता को प्रमुख मानता है। इस दृष्टिकोण में, सैन्य शक्ति को राष्ट्रीय सुरक्षा, विदेशी नीति, और राजनीतिक अधिकार का महत्वपूर्ण हिस्सा माना जाता है। सैन्यवाद के अनुयायी समझते हैं कि एक मजबूत और शक्तिशाली सेना राष्ट्र की सुरक्षा और समृद्धि की गारंटी होती है। इस प्रकार के विचारधारा में, सेना को अधिक महत्व दिया जाता है और युद्ध को समाधान के एकमात्र माध्यम के रूप में देखा जाता है। विपक्ष में, कई लोग सैन्यवाद को उच्चतम संज्ञान में देखते हैं और उन्हें शांति और विकास की बजाय समस्याओं का उत्तर मानते हैं।',0),(32,0,'स्वदेशी आन्दोलन','empty.png','swadeshi-movement',1,1,'स्वदेशी आंदोलन भारत में ब्रिटिश शासन के खिलाफ एक महत्वपूर्ण आंदोलन था, जो 1905 और 1908 के बीच आयोजित किया गया था। इस आंदोलन का मुख्य उद्देश्य ब्रिटिश उत्पादों के बहिष्कार और भारतीय उत्पादों का समर्थन करना था। इसका उद्देश्य था ब्रिटिश शासन के खिलाफ भारतीय जनता की आत्मगौरव को बढ़ाना और स्वतंत्रता के लिए एकत्रित करना। इस आंदोलन के प्रमुख नेता थे लाला लाजपत राय, बाल गंगाधर तिलक, और बिपिन चंद्र पाल जैसे महान स्वतंत्रता सेनानियों ने। इस आंदोलन ने भारतीय समुदाय को एक साथ लाने और उन्हें ब्रिटिश शासन के खिलाफ एकत्रित किया। इस आंदोलन ने भारतीय स्वतंत्रता संग्राम में एक महत्वपूर्ण धारावाहिक डाला।',1),(33,0,'हिटलर','empty.png','hitler',1,1,'हिटलर, जर्मन राजनीतिक नेता और द्वितीय विश्वयुद्ध के दौरान जर्मनी के चांसलर थे। उनका नाम ऐतिहासिक संदर्भ में उनके नाजी पार्टी के नेतृत्व में उत्कृष्ट और अत्यंत विवादास्पद रूप में जुड़ा है। हिटलर ने जर्मन समाज में विभाजन, आतंकवाद, और नशे के वाद में गहरे प्रभाव डाले। उनकी नाजी पार्टी ने यहूओं के खिलाफ उत्तेजना फैलाई और नाजी जर्मनी के शासनकाल में दुष्कर्मों, नाराजगी, और नशे का व्यापक प्रचार किया। उनके शासन के दौरान द्वितीय विश्वयुद्ध के अधिकांश घातक घटनाओं में उनका योगदान था। उनकी शासनकाल में शिक्षा, संगठन, और धार्मिक स्थान पर विवाद उत्पन्न हुआ, जिसका परिणाम उनके नाम पर किये गए अत्याचार और दुर्भाग्यपूर्ण इतिहास में दर्ज हुआ है।',1),(34,0,'मिस्र का इतिहास','empty.png','history-of-egypt',1,1,'मिस्र का इतिहास प्राचीन और समृद्ध है, जो लगभग 3100 ईसा पूर्व से शुरू होता है। प्रारंभिक राजवंशीय काल में मेनेस ने ऊपरी और निचली मिस्र को एकजुट किया। पुराना राज्य (2686-2181 ईसा पूर्व) पिरामिडों का युग था, जिसमें गीज़ा के महान पिरामिड बने। मध्य राज्य (2055-1650 ईसा पूर्व) में मिस्र ने अपनी सैन्य और सांस्कृतिक शक्ति को पुनः स्थापित किया, जबकि नया राज्य (1550-1077 ईसा पूर्व) मिस्र की सबसे बड़ी समृद्धि का काल था, जिसमें हाट्शेपसट और रामसेस II जैसे शासकों का शासन रहा। उत्तरार्द्ध काल (1077-332 ईसा पूर्व) में मिस्र पर विदेशी आक्रमणों का प्रभाव रहा। यूनानी और रोमन काल (332 ईसा पूर्व - 395 ईस्वी) में सिकंदर महान ने मिस्र पर विजय प्राप्त की और टॉलेमीक राजवंश का शासन शुरू हुआ। क्लियोपेट्रा VII इस राजवंश की आखिरी शासक थीं। 30 ईसा पूर्व में, रोमन साम्राज्य ने मिस्र को अपने साम्राज्य में शामिल कर लिया। मिस्र की सभ्यता ने कला, विज्ञान और स्थापत्य में महत्वपूर्ण योगदान दिया और विश्व इतिहास को एक नई दिशा दी। इसकी समृद्ध संस्कृति और महान स्थापत्य की विरासत आज भी विश्वभर में प्रशंसा पाती है।',3),(35,0,'आन्दोलन','movement.png','movement',1,1,'आन्दोलन एक सामाजिक, राजनीतिक या आर्थिक परिवर्तन के लिए जनसमूह द्वारा किया गया प्रयास होता है। यह आमतौर पर जनहित के लिए होता है और अधिकतर लोगों को एक सामान्य उद्देश्य के लिए एकत्रित करने का प्रयास करता है। आन्दोलन कई रूपों में हो सकता है, जैसे धर्मनिरपेक्षता, स्वतंत्रता, न्याय, और सामाजिक असमानता के खिलाफ। ये आंदोलन आमतौर पर धरना, प्रदर्शन, और आंदोलित सड़कों के माध्यम से सामाजिक परिवर्तन को प्रोत्साहित करते हैं।',20),(36,0,'गैर-ब्राह्मण आंदोलन','gba.jpg','gba',1,1,'गैर-ब्राह्मण आंदोलन 20वीं सदी की शुरुआत में दक्षिण भारत में उभरा एक सामाजिक और राजनीतिक आंदोलन था, जिसका उद्देश्य ब्राह्मण वर्चस्व को चुनौती देना और गैर-ब्राह्मणों के सामाजिक, शैक्षिक, और राजनीतिक अधिकारों के लिए संघर्ष करना था। इसे मुख्य रूप से पेरियार और जस्टिस पार्टी ने बढ़ावा दिया, और इस आंदोलन ने दक्षिण भारतीय राजनीति में महत्वपूर्ण बदलाव लाए।',2),(37,0,'Multiplication & Division','empty.png','multiplication-and-division',1,2,'',0),(38,0,'Number System','empty.png','number-system',1,2,'',0),(42,0,'जल प्रबंधन','water-management.png','water-management',1,5,'जल प्रबंधन प्राकृतिक जल संसाधनों के उचित उपयोग, संरक्षण और रखरखाव की प्रक्रिया है ताकि पानी की उपलब्धता को संतुलित रखा जा सके और भविष्य में जल संकट से बचा जा सके। यह कृषि, उद्योग, घरेलू उपयोग और पर्यावरणीय संतुलन के लिए अत्यंत आवश्यक है।',3),(43,0,'वन्यजीव','empty.png','wildlife',1,5,'वन्य जीव (Wildlife) उन सभी जीवों (पशु, पक्षी, कीट, सरीसृप, जल जीव और सूक्ष्म जीव) को संदर्भित करता है जो प्रकृति में स्वतंत्र रूप से बिना मानव हस्तक्षेप के रहते हैं। ये जीव जंगलों, घास के मैदानों, पर्वतीय क्षेत्रों, नदियों, झीलों और समुद्रों में पाए जाते हैं।',3),(44,0,'पर्यावरण प्रदूषण','environmental-pollution.png','environmental-pollution',1,5,'पर्यावरण प्रदूषण एक गंभीर समस्या है जो प्राकृतिक संसाधनों को दूषित कर जीव-जंतुओं और मानव जीवन के लिए खतरा पैदा करता है। बढ़ती जनसंख्या, औद्योगीकरण, शहरीकरण और वनों की कटाई के कारण प्रदूषण तेजी से बढ़ रहा है।',3),(45,0,'प्राकृतिक संसाधन','natural-resources.png','natural-resources',1,5,'प्राकृतिक संसाधन वे सभी तत्व हैं जो प्रकृति द्वारा प्रदान किए जाते हैं और जीवों के जीवनयापन के लिए आवश्यक होते हैं। ये संसाधन पृथ्वी, जल, वायु, खनिज, वनस्पति और जीव-जंतुओं के रूप में पाए जाते हैं। इनका उपयोग भोजन, ऊर्जा, निर्माण और औद्योगिक विकास में किया जाता है। प्राकृतिक संसाधनों को दो भागों में विभाजित किया जा सकता है— अक्षय संसाधन, जैसे सूर्य का प्रकाश, हवा और जल, जो निरंतर उपलब्ध रहते हैं, और अक्षय संसाधन, जैसे कोयला, पेट्रोलियम और खनिज, जो सीमित मात्रा में उपलब्ध हैं और समय के साथ समाप्त हो सकते हैं।',3),(46,0,'उद्योग','industries.png','industries',1,5,'उद्योग वह आर्थिक गतिविधि है जिसमें कच्चे माल को उपयोगी वस्तुओं में परिवर्तित किया जाता है। यह किसी भी देश की अर्थव्यवस्था की रीढ़ होती है और विकास में महत्वपूर्ण भूमिका निभाता है। उद्योगों को उनके स्वरूप और उत्पादों के आधार पर विभिन्न श्रेणियों में बांटा जाता है, जैसे— कुटीर उद्योग, जो छोटे स्तर पर होते हैं, लघु उद्योग, जो सीमित संसाधनों से संचालित होते हैं, और वृहद उद्योग, जिनमें बड़े पैमाने पर उत्पादन किया जाता है।',2),(59,0,'ब्रह्म समाजा','empty.png','brahmo-samaj',1,1,'ब्रह्म समाज भारतीय समाज सुधारक और धार्मिक आंदोलन था, जिसकी स्थापना 1828 में राजा राम मोहन राय ने की थी। इसका उद्देश्य हिंदू धर्म में सुधार लाना, अंधविश्वासों और कुरीतियों को समाप्त करना, और समाज में समानता और मानवता को बढ़ावा देना था।',0),(60,0,'सामाजिक सुधार','empty.png','social-reform',1,1,'सामाजिक सुधार समाज में फैली रूढ़ियों, कुरीतियों और असमानताओं को समाप्त करने का प्रयास है। यह आंदोलन समाज को अधिक न्यायपूर्ण, समतामूलक और उन्नत बनाने के लिए किया जाता है। भारत में 19वीं शताब्दी के दौरान सामाजिक सुधार आंदोलनों की शुरुआत हुई, जिनमें बाल विवाह, सती प्रथा, छुआछूत, स्त्री-पुरुष असमानता जैसी समस्याओं के खिलाफ आवाज उठाई गई। राजा राममोहन राय, ईश्वरचंद्र विद्यासागर, ज्योतिबा फुले जैसे समाज सुधारकों ने शिक्षा, नारी अधिकार और जातिगत भेदभाव के खिलाफ महत्वपूर्ण योगदान दिया। इन सुधारों ने आधुनिक भारत के निर्माण में अहम भूमिका निभाई।',4),(61,0,'सामाजिक आंदोलन','empty.png','social-movement',1,1,'सामाजिक आंदोलन समाज में परिवर्तन लाने के लिए किया गया संगठित प्रयास होता है। इसका उद्देश्य सामाजिक कुरीतियों, अन्याय, भेदभाव और असमानताओं को खत्म करना होता है। भारत में कई महत्वपूर्ण सामाजिक आंदोलनों हुए हैं, जैसे ब्रह्म समाज, आर्य समाज, दलित आंदोलन, नारी मुक्ति आंदोलन और चिपको आंदोलन। इन आंदोलनों ने शिक्षा, समानता, पर्यावरण संरक्षण और अधिकारों के लिए लोगों को जागरूक किया। सामाजिक आंदोलन समाज में चेतना और बदलाव लाने का सशक्त माध्यम होते हैं। ये आम जनता की भागीदारी से संचालित होते हैं और लोकतांत्रिक मूल्यों को मजबूत करते हैं।',5),(62,0,'भारतीय पुनर्जागरण','empty.png','indian-renaissance',1,1,'भारतीय पुनर्जागरण 19वीं और 20वीं शताब्दी के बीच भारत में हुआ एक सामाजिक, धार्मिक, सांस्कृतिक और बौद्धिक जागृति का आंदोलन था। इसका उद्देश्य भारतीय समाज को अंधविश्वास, कुरीतियों और सामाजिक बुराइयों से मुक्त कर प्रगति की ओर ले जाना था। इस काल में शिक्षा, विज्ञान, मानवाधिकार, नारी सशक्तिकरण और धार्मिक सुधारों पर जोर दिया गया। राजा राममोहन राय, स्वामी विवेकानंद, ईश्वरचंद्र विद्यासागर, दयानंद सरस्वती, ज्योतिबा फुले और डॉ. भीमराव आंबेडकर जैसे महान नेताओं ने इसमें महत्वपूर्ण भूमिका निभाई। इस आंदोलन ने आधुनिक भारत के निर्माण की नींव रखी और राष्ट्रीय चेतना को जाग्रत किया।',0),(63,0,'राजनीतिक दर्शन','empty.png','ancient-political-philosophy',1,1,'राजनीतिक दर्शन राज्य, सत्ता, न्याय, स्वतंत्रता, अधिकार और शासन के नैतिक एवं सैद्धांतिक पक्षों का अध्ययन करता है। यह विचार करता है कि आदर्श राज्य कैसा हो, न्यायपूर्ण समाज कैसे बने, और नागरिकों के अधिकार व कर्तव्य क्या हों। प्लेटो ने आदर्श राज्य और दार्शनिक राजा की संकल्पना दी, जबकि अरस्तू ने राज्य को नैतिक विकास का माध्यम बताया। रूसो ने सामाजिक अनुबंध और सामान्य इच्छा की बात की, वहीं लॉक ने प्राकृतिक अधिकारों और सीमित सरकार पर बल दिया। हॉब्स ने सुरक्षा हेतु निरंकुश सत्ता का समर्थन किया। गांधी ने नैतिकता और अहिंसा को राजनीति में जोड़ा। राजनीतिक दर्शन लोकतंत्र, समानता और न्याय के सिद्धांतों को समझने और लागू करने का मार्ग प्रशस्त करता है।',5),(64,0,'प्राचीन भारतीय राजनीतिक दर्शन','empty.png','ancient-indian-political-philosophy',1,1,'प्राचीन भारतीय राजनीतिक दर्शन राज्य, शासन, न्याय और नीति संबंधी विचारों का प्राचीन भारत में विकसित गहन चिंतन है। इसके मुख्य स्रोत वेद, महाभारत, रामायण, Manusmriti, और विशेष रूप से कौटिल्य का अर्थशास्त्र हैं। कौटिल्य ने राज्य की सात अंगों वाली संरचना (सप्तांग सिद्धांत) और मंडल सिद्धांत द्वारा विदेशी नीति का विश्लेषण किया। प्राचीन विचारकों ने धर्म (नैतिकता), अर्थ (संपत्ति), और दंड (शासन शक्ति) के संतुलन को शासन का आधार माना। राजा को प्रजा का रक्षक और धर्म का पालक बताया गया। नीति, कूटनीति, जासूसी, युद्धनीति जैसे विषयों पर गहराई से विचार किया गया। यह दर्शन न केवल व्यावहारिक शासन तंत्र देता है, बल्कि नैतिक और सामाजिक मूल्यों को भी प्राथमिकता देता है।',2),(65,0,'कूटनीतिक सिद्धांत','empty.png','theory-of-diplomacy',1,1,'कूटनीतिक सिद्धांत उन नीतियों और व्यवहारों का अध्ययन है जो एक राज्य दूसरे राज्य से संबंध स्थापित करने, उन्हें बनाए रखने या अपने हित साधने हेतु अपनाता है। प्राचीन भारतीय संदर्भ में कौटिल्य का कूटनीति पर आधारित मंडल सिद्धांत विशेष रूप से प्रसिद्ध है। इसके अनुसार पड़ोसी राज्य संभावित शत्रु होता है, जबकि उसका पड़ोसी मित्र होता है। कौटिल्य ने छह कूटनीतिक नीतियाँ बताईं: संधि (संधान), विग्रह (युद्ध), यान (आक्रमण), आसन (तटस्थता), संश्रय (सहयोग) और द्वैधीभाव (दोहरा व्यवहार)। कूटनीति का उद्देश्य सत्ता संतुलन बनाए रखना और राज्य के दीर्घकालिक हितों की रक्षा करना होता है। यह सिद्धांत आज के अंतरराष्ट्रीय संबंधों की नींव रखने वाले मूल विचारों में शामिल है।',2),(66,0,'राजनीतिक प्रशासन','empty.png','political-administration',1,1,'राजनीतिक प्रशासन वह व्यवस्था है जिसके माध्यम से सरकार के नीतिगत निर्णय बनते हैं और उन्हें लागू किया जाता है। इसमें राजनीतिक नेतृत्व जैसे मंत्री, विधायक, सांसद शामिल होते हैं जो जनता के हित में नीतियां बनाते हैं। राजनीतिक प्रशासन जनता की इच्छाओं और जरूरतों को ध्यान में रखकर सरकारी कामकाज को संचालित करता है। यह प्रशासन सरकारी नीतियों, योजनाओं और कानूनों को लागू करने का काम करता है और देश की शासन प्रणाली को प्रभावी बनाता है। राजनीतिक प्रशासन लोकतंत्र का आधार है, जो जनप्रतिनिधियों और प्रशासन के बीच संतुलन बनाए रखता है।',4),(67,0,'आर्थिक प्रशासन','empty.png','economic-administration',1,1,'आर्थिक प्रशासन वह प्रक्रिया है जिसके माध्यम से किसी देश या संस्था की आर्थिक नीतियाँ बनाई और लागू की जाती हैं। इसमें बजट निर्माण, कर प्रणाली, वित्तीय प्रबंधन, और आर्थिक संसाधनों का वितरण शामिल होता है। इसका उद्देश्य आर्थिक विकास को बढ़ावा देना, रोजगार सृजन करना, और समाज के सभी वर्गों के लिए समृद्धि सुनिश्चित करना होता है। आर्थिक प्रशासन सरकार द्वारा वित्तीय नियंत्रण और नियमन के माध्यम से आर्थिक स्थिरता बनाए रखता है। यह उत्पादन, वितरण, और उपभोग की गतिविधियों को संगठित करके देश की आर्थिक योजनाओं को सफल बनाता है।',7),(68,0,'सैन्य प्रशासन','empty.png','military-administration',1,1,'सैन्य प्रशासन वह प्रणाली है जिसके तहत सेना का संगठन, संचालन, और प्रबंधन किया जाता है। इसमें सैनिकों की भर्ती, प्रशिक्षण, अनुशासन, और युद्ध के लिए तैयार करना शामिल है। सैन्य प्रशासन का उद्देश्य सेना को मजबूत, अनुशासित और युद्ध के लिए तत्पर बनाना होता है। यह प्रशासन युद्ध रणनीति, हथियार प्रबंधन, और सैन्य संसाधनों के सही उपयोग को सुनिश्चित करता है। सैन्य अधिकारियों के आदेशों का पालन करना और सामरिक योजनाओं को लागू करना भी इसका हिस्सा है। यह प्रशासन देश की सुरक्षा और रक्षा के लिए महत्वपूर्ण भूमिका निभाता है।',6),(69,0,'न्यायिक प्रशासन','empty.png','judicial-administration',1,1,'न्यायिक प्रशासन वह प्रणाली है जो न्याय व्यवस्था को सुचारू रूप से चलाने के लिए जिम्मेदार होती है। इसमें अदालतों का संचालन, मुकदमों की सुनवाई, न्यायाधीशों और कर्मचारीयों का प्रबंधन शामिल होता है। इसका मुख्य उद्देश्य कानून का सही और निष्पक्ष पालन सुनिश्चित करना है। न्यायिक प्रशासन के माध्यम से लोगों को न्याय दिलाना, कानूनी विवादों का समाधान करना और विधि व्यवस्था बनाए रखना संभव होता है। यह प्रशासन न्यायिक प्रक्रिया को तेज, पारदर्शी और सुलभ बनाने पर भी ध्यान देता है ताकि समाज में कानून का शासन कायम रहे।',6),(70,1,'Short Question','empty.png','short',0,1,'',0);
